DROP TABLE IF EXISTS `mes_pqc_process_inspection_aggregate_detail`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `mes_pqc_process_inspection_aggregate_detail` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '编号',
  `source_pqc_record_id` bigint NOT NULL COMMENT '来源工序池PQC记录ID',
  `event_id` bigint NOT NULL COMMENT 'PQC提交事件ID',
  `review_id` bigint NOT NULL COMMENT 'PQC组长复核ID',
  `production_submit_event_id` bigint NOT NULL COMMENT '绑定生产提交事件ID',
  `pqc_task_id` bigint NOT NULL COMMENT 'PQC检验任务ID',
  `active_order_id` bigint DEFAULT NULL COMMENT '活跃订单ID',
  `work_order_id` bigint NOT NULL COMMENT '生产订单ID',
  `route_id` bigint NOT NULL COMMENT '工艺路线ID',
  `route_version_id` bigint NOT NULL COMMENT '工艺路线版本ID',
  `route_process_id` bigint NOT NULL COMMENT '工艺路线工序ID',
  `process_id` bigint NOT NULL COMMENT '工序ID',
  `regulation_version_id` bigint NOT NULL COMMENT 'QA规程发布版本ID',
  `inspection_type` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '检验类型',
  `business_date` date NOT NULL COMMENT '业务日期',
  `shift_code` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '班次编码',
  `round_no` int NOT NULL COMMENT '轮次',
  `source_piece_detail_id` bigint NOT NULL COMMENT '来源逐件检验明细ID',
  `sample_no` int NOT NULL COMMENT '逐件样本序号',
  `item_code` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '检验项目编码',
  `item_name` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '检验项目名称',
  `inspection_method` varchar(512) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '检验方法',
  `standard_text` varchar(1024) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '合格标准',
  `selected_equipment_id` bigint DEFAULT NULL COMMENT '实际检验设备ID快照',
  `selected_equipment_code` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '实际检验设备编码快照',
  `selected_equipment_name` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '实际检验设备名称快照',
  `selected_equipment_number` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '实际检验设备编号快照',
  `standard_lower_limit` decimal(18,6) DEFAULT NULL COMMENT '接收标准下限快照',
  `standard_upper_limit` decimal(18,6) DEFAULT NULL COMMENT '接收标准上限快照',
  `standard_unit` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '接收标准单位快照',
  `standard_precision` int DEFAULT NULL COMMENT '接收标准精度快照',
  `result_type` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '结果类型',
  `item_result` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '检验结果',
  `measured_value` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '实测值',
  `judgement` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '判定',
  `aggregated_at` datetime NOT NULL COMMENT '汇集时间',
  `creator` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  `tenant_id` bigint NOT NULL DEFAULT '0' COMMENT '租户编号',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_mes_pqc_process_aggregate_piece` (`tenant_id`,`source_piece_detail_id`,`review_id`,`deleted`),
  KEY `idx_mes_pqc_process_aggregate_event` (`tenant_id`,`event_id`,`review_id`),
  KEY `idx_mes_pqc_process_aggregate_task` (`tenant_id`,`pqc_task_id`,`sample_no`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='MES PQC 过程检验汇集明细';
/*!40101 SET character_set_client = @saved_cs_client */;

LOCK TABLES `mes_pqc_process_inspection_aggregate_detail` WRITE;
/*!40000 ALTER TABLE `mes_pqc_process_inspection_aggregate_detail` DISABLE KEYS */;
/*!40000 ALTER TABLE `mes_pqc_process_inspection_aggregate_detail` ENABLE KEYS */;
