/*!40000 ALTER TABLE `mes_pro_process_pool_submission_review` ENABLE KEYS */;
UNLOCK TABLES;
DROP TABLE IF EXISTS `mes_pro_process_pool_pqc_record`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `mes_pro_process_pool_pqc_record` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT 'PQC 工序池过程检验记录ID',
  `pool_id` bigint NOT NULL COMMENT '工序池ID',
  `event_id` bigint NOT NULL COMMENT '工序池提交事件ID',
  `production_submit_event_id` bigint NOT NULL COMMENT '正式绑定的生产提交事件ID',
  `work_order_id` bigint NOT NULL COMMENT '生产工单ID',
  `route_id` bigint NOT NULL COMMENT '工艺路线ID',
  `route_process_id` bigint NOT NULL COMMENT '路线工序ID',
  `process_id` bigint NOT NULL COMMENT '工序ID',
  `actual_employee_id` bigint NOT NULL COMMENT '实际员工ID',
  `signature_id` bigint NOT NULL COMMENT '电子签名ID',
  `signature_user_id` bigint NOT NULL COMMENT '电子签名用户ID',
  `inspection_result` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '过程检验结果',
  `server_submit_time` datetime NOT NULL COMMENT '服务端提交时间',
  `raw_payload` json NOT NULL COMMENT 'PQC 原始 payload',
  `process_inspection_aggregation_status` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'PENDING' COMMENT '过程检验汇集状态：PENDING/AGGREGATED',
  `process_inspection_review_id` bigint DEFAULT NULL COMMENT '触发过程检验汇集的PQC组长复核ID',
  `process_inspection_aggregated_at` datetime DEFAULT NULL COMMENT '过程检验汇集时间',
  `creator` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  `tenant_id` bigint NOT NULL DEFAULT '0' COMMENT '租户编号',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_mes_pro_process_pool_pqc_event` (`tenant_id`,`event_id`,`deleted`),
  KEY `idx_mes_pro_process_pool_pqc_event` (`tenant_id`,`event_id`),
  KEY `idx_mes_pro_process_pool_pqc_pool` (`tenant_id`,`pool_id`),
  KEY `idx_mes_pp_pqc_process_inspection` (`tenant_id`,`work_order_id`,`route_process_id`,`process_id`,`process_inspection_aggregation_status`),
  KEY `idx_mes_pro_process_pool_pqc_submit_event` (`tenant_id`,`production_submit_event_id`)
) ENGINE=InnoDB AUTO_INCREMENT=99 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='MES 工序池 PQC 过程检验记录';
/*!40101 SET character_set_client = @saved_cs_client */;

LOCK TABLES `mes_pro_process_pool_pqc_record` WRITE;
